import { PriceLabel } from './PriceLabel'
@Component
export struct ProductTile {
 @Prop title: string = ''
 @Prop amount: string = ''
 build() {
  Column() {
   Text(this.title).fontSize(18)
   PriceLabel({ amount: this.amount })
  }
 }
}

